export type Target =
  | { t: "slide"; v: number }
  | { t: "all" };


export function writeTarget(w: Writer, v: Target, t: Tables): void {
  void t;
  switch (v.t) {
    case "slide":
      w.u32(0);
      w.i32(v.v);
      break;

    case "all":
      w.u32(1);
      break;

    default:
      throw new EncodeError(`"${String((v as { t: string }).t)}" is not a variant of Target`);

  }
}

export function readTarget(r: Reader, t: Tables): Target {
  void t;
  const tag = r.u32();
  let out: Target;
  switch (tag) {
    case 0:
      out = { t: "slide", v: r.i32() };
      break;

    case 1:
      out = { t: "all" };
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of Target`);

  }
  return out;
}

