/**
 * a copied shape: its XML, the relations it cites (with the bytes of the parts they point at), its text and the
 * identity of the editor it came from (`source_id`: pasting in the same editor shares the parts)
 */
export interface ShapeClip {
  xml: string;
  rels: ClipRel[];
  text: string;
  sourceId: number;
  slidePath: string;
}

export function writeShapeClip(w: Writer, v: ShapeClip, t: Tables): void {
  void t;
  w.utf16(v.xml);
  w.len(v.rels.length);
  for (const e0 of v.rels) {
    writeClipRel(w, e0, t);
  }
  w.utf16(v.text);
  w.f64(v.sourceId);
  w.utf16(v.slidePath);
}

export function readShapeClip(r: Reader, t: Tables): ShapeClip {
  void t;
  const f_xml = r.utf16();
  const f_rels = r.list(32, () => readClipRel(r, t));
  const f_text = r.utf16();
  const f_source_id = r.f64();
  const f_slide_path = r.utf16();
  const o: ShapeClip = { xml: f_xml, rels: f_rels, text: f_text, sourceId: f_source_id, slidePath: f_slide_path };
  return o;
}

